// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.bulk;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

class BulkCompressionTest {

	@Test
	void parsesFastest() {
		assertThat(BulkCompression.parse("fastest")).isEqualTo(BulkCompression.FASTEST);
		assertThat(BulkCompression.FASTEST.token()).isEqualTo("fastest");
	}

	@Test
	void parsesNone() {
		assertThat(BulkCompression.parse("none")).isEqualTo(BulkCompression.NONE);
		assertThat(BulkCompression.NONE.token()).isEqualTo("none");
	}

	@Test
	void parsesHighCompressionLevels() {
		assertThat(BulkCompression.parse("1")).isEqualTo(BulkCompression.level(1));
		assertThat(BulkCompression.parse("9")).isEqualTo(BulkCompression.level(9));
		assertThat(BulkCompression.parse("17")).isEqualTo(BulkCompression.level(17));
		assertThat(BulkCompression.level(9).token()).isEqualTo("9");
	}

	@Test
	void ignoresSurroundingWhitespaceAndCase() {
		assertThat(BulkCompression.parse("  FASTEST ")).isEqualTo(BulkCompression.FASTEST);
		assertThat(BulkCompression.parse(" None")).isEqualTo(BulkCompression.NONE);
		assertThat(BulkCompression.parse(" 12 ")).isEqualTo(BulkCompression.level(12));
	}

	@Test
	void tokensRoundTripThroughParse() {
		assertThat(BulkCompression.parse(BulkCompression.FASTEST.token())).isEqualTo(BulkCompression.FASTEST);
		assertThat(BulkCompression.parse(BulkCompression.NONE.token())).isEqualTo(BulkCompression.NONE);
		for (int level = 1; level <= 17; level++) {
			BulkCompression compression = BulkCompression.level(level);
			assertThat(BulkCompression.parse(compression.token())).isEqualTo(compression);
		}
	}

	/**
	 * {@code LZ4Factory.highCompressor(int)} silently clamps out-of-range levels: anything above 17 becomes 17 and
	 * anything below 1 becomes the default 9. Reject them here instead so a typo cannot masquerade as a valid setting.
	 */
	@ParameterizedTest
	@ValueSource(ints = { -1, 0, 18, 100 })
	void rejectsOutOfRangeLevels(int level) {
		assertThatThrownBy(() -> BulkCompression.level(level))
				.isInstanceOf(IllegalArgumentException.class)
				.hasMessageContaining("between 1 and 17");
	}

	@ParameterizedTest
	@ValueSource(strings = { "0", "18", "fast", "high", "lz4", "", "9.5", "-3" })
	void rejectsUnparseableTokens(String token) {
		assertThatThrownBy(() -> BulkCompression.parse(token)).isInstanceOf(IllegalArgumentException.class);
	}

	@Test
	void rejectsNullToken() {
		assertThatThrownBy(() -> BulkCompression.parse(null)).isInstanceOf(NullPointerException.class);
	}

	@Test
	void exposesTheEffectiveCodecKind() {
		assertThat(BulkCompression.FASTEST.kind()).isEqualTo(BulkCompression.Kind.FASTEST);
		assertThat(BulkCompression.NONE.kind()).isEqualTo(BulkCompression.Kind.NONE);
		assertThat(BulkCompression.level(4).kind()).isEqualTo(BulkCompression.Kind.HIGH);
		assertThat(BulkCompression.level(4).level()).isEqualTo(4);
	}
}
